#!/usr/bin/env bash
set -euo pipefail

# Count occurrences of the first field (IP) and print the top three,
# ties broken by first appearance in the log.
awk '
{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    # Simple selection sort of the top 3 by (count desc, first-seen asc)
    for (i = 1; i <= 3; i++) {
        best = 0
        for (j = 1; j <= n; j++) {
            if (used[j]) continue
            if (best == 0 ||
                count[order[j]] > count[order[best]] ||
                (count[order[j]] == count[order[best]] && j < best)) {
                best = j
            }
        }
        if (best == 0) break
        print order[best]
        used[best] = 1
    }
}
' access.log
